import {weeklyPlans,weeklyInsights} from './weekly-ui-e14b41d62339.mjs';
import {PRIMARY_PAGES,PAGE_TITLES,returnTitle} from './navigation-e14b41d62339.mjs';
import {homeView} from './home-view-e14b41d62339.mjs';
import {timelineEntries} from './timeline-model-e14b41d62339.mjs';
import {createGrowthViews} from './growth-views-e14b41d62339.mjs';
import {APP_VERSION} from './version-e14b41d62339.mjs';
import * as D from './domain-e14b41d62339.mjs';
import {compositionCard,growthOverview} from './insights-e14b41d62339.mjs';
import {diaryCollection} from './diary-e14b41d62339.mjs';
import {themeSettings} from './theme-e14b41d62339.mjs';
import {onboardingBanner} from './onboarding-e14b41d62339.mjs';
import {phoneCard,phoneSettings} from './phone-ui-e14b41d62339.mjs';
import {duration} from './duration-format-e14b41d62339.mjs';
export {duration} from './duration-format-e14b41d62339.mjs';
export const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const icons={today:'◷',growth:'✧',plans:'⚑',memory:'▤',insights:'▥',settings:'⚙'};
export const titles=PAGE_TITLES;
export const num=n=>n>0&&n<0.01?'< 0.01':Number(n.toFixed(2)).toLocaleString('zh-CN');
export const progressNum=n=>n>0&&n<0.01?'< 0.01':Number((Math.floor(n*100)/100).toFixed(2)).toLocaleString('zh-CN');
export const clock=(ms,zone='Asia/Shanghai',seconds=false)=>new Intl.DateTimeFormat('zh-CN',{timeZone:zone,hour:'2-digit',minute:'2-digit',...(seconds?{second:'2-digit'}:{}),hourCycle:'h23'}).format(ms);
const longDate=d=>new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long',timeZone:'UTC'}).format(new Date(d+'T12:00Z'));
const button=(action,label,cls='',id='')=>`<button type="button" class="${cls}" data-action="${action}" ${id?`data-id="${e(id)}"`:''}>${label}</button>`;
export const empty=(title,body,action='',label='')=>`<div class="empty"><span class="empty-star" aria-hidden="true">✧</span><h3>${title}</h3><p>${body}</p>${action?button(action,label,'secondary'):''}</div>`;
export const bar=ratio=>`<div class="progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.floor(Math.max(0,Math.min(1,ratio))*100)}"><span style="width:${Math.max(0,Math.min(ratio<1?.995:1,ratio))*100}%"></span></div>`;
export function shell(state,ui,content){
  const nav=PRIMARY_PAGES.map(key=>`<button type="button" data-nav="${key}" class="nav-item ${(ui.navPage||ui.page)===key?'active':''}" ${(ui.navPage||ui.page)===key?'aria-current="page"':''}><span aria-hidden="true">${icons[key]}</span><b>${titles[key]}</b></button>`).join('');
  return `<aside class="sidebar"><div class="brand"><div class="brand-mark">N<span>◇</span></div><p>NO GAME<br>NO LIFE<span>日常，也有自己的光。</span></p></div><nav aria-label="主导航">${nav}</nav><div class="sidebar-bottom"><i></i> 只属于你的本地记录<small>LOCAL EDITION / ${APP_VERSION}</small></div></aside>
  <main id="main" tabindex="-1"><header class="topbar"><div><span class="eyebrow">YOUR LIFE, AT YOUR PACE</span><p>${titles[ui.page]||(ui.page==='stageOverview'?'阶段总览':'培养明细')}</p></div><div class="top-actions">${state.running?`<button type="button" class="running-pill" data-nav="today"><i></i>${e(state.running.name)} <span data-live-small></span></button>`:''}<button type="button" data-nav="settings" class="save-status settings-entry" title="设置、完整备份与恢复"><span aria-hidden="true">⚙</span> 设置与数据</button></div></header>${ui.needsRecovery&&state.running?`<div class="recovery-banner"><span>上次的${e(state.running.name)}有未确认的尾段，可以稍后处理。</span><button type="button" class="secondary" data-action="recovery">核对计时</button></div>`:''}${['settings','insights'].includes(ui.page)&&ui.viewTrail?.length?`<button type="button" class="text-button page-return" data-action="page-back">‹ 返回${e(returnTitle(ui))}</button>`:''}${content}<footer class="page-footer">NO GAME NO LIFE <span>·</span> 每一段真实的投入，都留在这里。</footer></main><nav class="mobile-nav" aria-label="手机主导航">${nav}</nav>`;
}
export function timeline(state,date,{memory=false}={}){
  const entries=timelineEntries(state,date,{memory});
  return entries.map(item=>{
    const r=item.row,zone=state.timeZone,meta='data-timeline-kind="'+item.type+'" data-timeline-start="'+item.start+'"';
    if(item.type==='gap')return '<div class="timeline-gap" '+meta+'>'+clock(item.start,zone)+'—'+clock(item.end,zone)+' <span>未记录</span></div>';
    if(item.type==='moment')return '<div class="timeline-row moment-row" '+meta+'><time>'+clock(r.at,zone)+'</time><span class="timeline-dot" style="--dot:#b79b64"></span><div class="row-content"><button type="button" class="row-title" data-action="moment" data-id="'+e(r.id)+'">'+e(r.title||'生活片段')+'</button>'+momentContent(r)+'</div><span class="tag">片段</span></div>';
    if(item.type==='running')return '<div class="timeline-row running-row" '+meta+'><time>'+clock(item.start,zone)+'</time><span class="timeline-dot" style="--dot:#648a73"></span><div class="row-content"><strong>'+e(r.name)+'</strong><div class="row-meta">计时中 · 今天尚无已确认时段</div></div><span class="live-dot">进行中</span></div>';
    const moments=state.moments.filter(m=>m.sessionId===r.id),isRunning=r.id===state.running?.id;
    return '<div class="timeline-row'+(isRunning?' running-row':'')+'" '+meta+'><time>'+clock(item.start,zone)+'<small>'+clock(item.end,zone)+'</small></time><span class="timeline-dot" style="--dot:'+e(r.color)+'"></span><div class="row-content">'+(isRunning?'<strong class="row-title">'+e(r.name)+'</strong>':'<button type="button" class="row-title" data-action="session" data-id="'+e(r.id)+'">'+e(r.name)+'</button>')+(memory?moments.map(momentContent).join(''):'')+'<div class="row-meta">'+e(r.category)+(isRunning?' · 计时中 · 已确认部分':'')+(r.mainSkillId?' · '+e(state.skills.find(s=>s.id===r.mainSkillId)?.name??''):'')+(r.precision==='minute'?' · 按分钟补记':'')+(!memory&&moments.length?' · 有图文':'')+'</div></div><div class="row-tail"><strong>'+duration((item.end-item.start)/60000)+'</strong>'+(isRunning?button('recovery','核对计时','text-button'):memory?button('moment-for-session','＋','icon-button',r.id):button('edit-session','修正','text-button',r.id))+'</div></div>';
  }).join('')||empty('这一天，还没有记录','从现在开始，也可以只补上记得清楚的一段。','add-session','补记一段');
}
export function momentContent(m){return `<div class="moment-content">${m.text?`<p>${e(m.text).replace(/\n/g,'<br>')}</p>`:''}${m.photos.length?`<div class="thumbnails">${m.photos.map((p,i)=>`<button type="button" data-action="photo" data-id="${e(m.id)}" data-index="${i}" aria-label="查看照片 ${e(p.name)}"><img src="${e(p.data)}" alt="${e(p.name)}" loading="lazy"></button>`).join('')}</div>`:''}${m.text||m.photos.length?button('moment','编辑片段','text-button',m.id):''}</div>`;}
export function dateControl(ui){return `<div class="date-control"><button type="button" data-action="prev-date" aria-label="前一天">‹</button><input type="date" aria-label="查看日期" id="view-date" value="${ui.date}"><button type="button" data-action="next-date" aria-label="后一天">›</button></div>`;}
export function today(state,ui){return homeView(state,ui,{e,num,button,duration,clock,longDate,compositionCard,onboardingBanner,timeline,planCard,phoneCard});}
export function planCard(state,p,compact=false){const v=D.planProgress(state,p);return `<div class="plan-card ${compact?'compact':''}"><div class="plan-top"><h3>${e(p.title)}</h3>${p.focus?'<span class="tag gold">今日重点</span>':''}</div><p class="muted">${p.startDate.slice(5)} — ${p.endDate.slice(5)}</p>${p.targetMinutes?`<div class="progress-caption"><strong>${duration(v.minutes)}</strong><span>/ ${duration(p.targetMinutes)}</span></div>${bar(v.ratio)}`:''}${p.outcome?`<div class="outcome-line"><span class="${p.completedAt?'done':''}">${p.completedAt?'✓':'○'}</span><p>${e(p.outcome)}</p></div>`:''}<div class="plan-actions">${p.outcome?button('complete-plan',p.completedAt?'查看达成 ✓':'确认成果完成',p.completedAt?'text-button':'secondary',p.id):''}${!compact?button('stage-overview','阶段总览 ›','secondary',p.id):''}${!compact?button('edit-plan','编辑','text-button',p.id):''}${!p.focus&&!compact?button('focus-plan','设为今日重点','text-button',p.id):''}</div></div>`;}
function originalPlans(state,ui){
 const date=D.dateKey(Date.now(),state.timeZone),active=state.plans.filter(p=>p.endDate>=date),old=state.plans.filter(p=>p.endDate<date);
 const short=p=>`<section class="card stage-summary"><div class="section-title"><div><h2>${e(p.title)}</h2><p class="muted">${p.startDate}—${p.endDate}</p></div>${p.focus?'<span class="tag gold">今日重点</span>':''}</div><div class="stage-actions"><span>${p.targetMinutes?duration(D.planProgress(state,p).minutes)+' / '+duration(p.targetMinutes):'成果型阶段'}</span>${button('stage-overview','阶段总览 ›','secondary',p.id)}</div><details id="plan-manage-${e(p.id)}" data-preserve><summary>编辑与成果</summary>${planCard(state,p)}</details></section>`;
 return `<section class="heading compact-heading"><div><h1>阶段</h1><p>当前与未来的计划</p></div>${button('new-plan','＋ 新建阶段','primary')}</section><div class="plans-grid">${active.map(short).join('')||empty('还没有阶段计划','可以用一周、十天，或任意一段适合你的日期。','new-plan','新建阶段')}</div>${old.length?`<details class="card section-fold" id="plans-past" data-preserve><summary>往期阶段 · ${old.length}项</summary><div class="plans-grid">${old.map(short).join('')}</div></details>`:''}`;
}
const growthPages=()=>createGrowthViews({e,num,progressNum,duration,clock,bar,button,empty});
export function growth(state,ui){return growthPages().growth(state,ui);}
export function stageOverview(state,ui){return growthPages().overview(state,ui);}
export function skillDetail(state,ui){return growthPages().skillDetail(state,ui);}
export function memory(state,ui){return diaryCollection(state,ui,{e,dateControl,momentContent});}
function originalInsights(state,ui){const start=ui.statsStart||D.addDays(ui.date,-6),end=ui.statsEnd||ui.date,v=D.summarize(state,start,end),days=[];for(let d=start;d<=end&&days.length<366;d=D.addDays(d,1))days.push(d);const dayStats=days.map(d=>({d,...D.summarize(state,d,d)})),max=Math.max(60,...dayStats.map(v=>v.totalMinutes));return `<section class="heading compact-heading"><div><h1>统计</h1><p>按实际发生的日期分配，空白保留。</p></div></section><section class="card"><form id="stats-range" class="range-form"><label>开始日期<input name="start" type="date" value="${start}" required></label><label>结束日期<input name="end" type="date" value="${end}" required></label><button class="secondary">查看统计</button>${button('stats-today','今日','text-button')}${button('stats-week','最近七天','text-button')}</form></section><section class="card stat-overview"><div><span>已记录</span><strong>${duration(v.totalMinutes)}</strong></div><div><span>主线投入</span><strong>${duration(v.mainlineMinutes)}</strong></div><div><span>覆盖日期</span><strong>${days.length}<small> 天</small></strong></div></section><details id="stats-distribution" data-preserve class="card section-fold"><summary>活动分布与每日投入</summary><div class="two-columns"><section class="card"><h2>活动分布</h2><div class="distribution">${Object.entries(v.byName).sort((a,b)=>b[1]-a[1]).map(([name,n])=>`<div><div class="progress-caption"><strong>${e(name)}</strong><span>${duration(n)}</span></div>${bar(n/Math.max(v.totalMinutes,1))}</div>`).join('')||empty('还没有可统计的记录','记录会自然汇集到这里。')}</div></section><section class="card"><h2>每天的投入</h2><div class="daily-chart">${dayStats.map(v=>`<div class="chart-col" title="${v.d} ${duration(v.totalMinutes)}"><span>${duration(v.totalMinutes)}</span><div class="chart-bar"><i style="height:${Math.max(1,v.totalMinutes/max*100)}%"></i></div><small>${v.d.slice(5)}</small></div>`).join('')}</div><p class="quiet-note">包含所有已确认活动。主线由活动设置决定，关联贡献不增加生活分钟。</p></section></div></details><section class="card"><div class="section-title"><h2>按日查看</h2>${dateControl(ui)}</div></section><details class="card section-fold" id="stats-records" data-preserve ${ui.revealDay?'open':''}><summary>按日核对 · ${ui.date}</summary>${ui.category?`<p>${e(ui.category)} · ${button('clear-category','显示全部','text-button')}</p>`:''}${timeline(ui.category?{...state,sessions:state.sessions.filter(r=>r.category===ui.category),running:state.running?.category===ui.category?state.running:null}:state,ui.date)}</details>${state.phone||ui.nativeStatus?.available?`<details class="card section-fold" id="stats-phone" data-preserve ${ui.phoneFocus?'open':''}><summary>手机使用 · ${ui.date}</summary>${phoneCard(state,{e,duration,clock,date:ui.date})}${ui.viewTrail?.length?button('page-back','‹ 返回'+returnTitle(ui)+(ui.viewTrail.at(-1).page==='today'?'手机摘要':''),'text-button'):''}</details>`:''}`;}
export function settings(state,ui){const photoCount=state.moments.reduce((n,m)=>n+m.photos.length,0);return `<section class="heading"><div><span class="eyebrow">YOUR DATA, YOUR OWN</span><h1>把记录，好好留住。</h1><p>${ui.native?'数据保存在这部手机的应用里；无需登录，也不依赖电脑。':'数据保存在当前设备、当前浏览器；换浏览器或网址会是独立空间。'}</p></div></section><section class="card" id="backup-section"><div class="section-title"><h2>完整备份与恢复</h2><span class="tag">含照片</span></div><p>目前有 ${state.sessions.length} 条已结束活动、${state.moments.length} 个图文片段、${photoCount} 张照片。导出的备份包含计时、培养项、自评、阶段、图文、情境、手机记录、主题和未保存草稿。</p><div class="settings-actions">${button('backup','↓ 导出完整备份','primary')}<label class="secondary file-button">导入备份<input id="import-backup" type="file" accept=".json,application/json" hidden></label>${button('restore-point','恢复上次替换前的数据','text-button')}</div><p class="quiet-note">导入先校验并预览；替换前自动在本机保留一个恢复点。备份文件由你保存，建议定期导出到安全位置。</p></section>${state.settings.phone?.enabled&&ui.nativeStatus?.available&&(!ui.nativeStatus.usageAllowed||!ui.nativeStatus.notificationsAllowed||!ui.nativeStatus.running)?'<p class="form-error settings-notice">手机记录需要核对权限或后台状态，已保存记录保留。请打开下方手机管理检查。</p>':''}<details class="card section-fold" id="settings-appearance" data-preserve><summary>外观与动效</summary>${themeSettings(state)}</details><details class="card section-fold" id="settings-phone" data-preserve><summary>手机管理与权限</summary>${phoneSettings(state,ui,{e,duration,clock})}</details><section class="card"><details id="settings-compat" data-preserve><summary>升级与旧版兼容导出</summary><p>新版完整备份保留所有数据。以下仅用于需要旧版读取的情况，不会更改当前应用。</p><div class="settings-actions">${button('export-original','导出升级前原始备份','secondary')}${button('export-legacy','导出当前旧版兼容数据','secondary')}</div></details></section><details class="card section-fold" id="settings-device" data-preserve><summary>设备、保存与离线</summary><div class="two-columns"><section class="card"><h2>设备与保存</h2><dl class="info-list"><div><dt>当前数据空间</dt><dd>${ui.native?'安卓应用 · '+APP_VERSION:e(location.origin)+' · '+APP_VERSION}</dd></div><div><dt>日期口径</dt><dd>${e(state.timeZone)} · 跨日拆分统计</dd></div><div><dt>离线资源</dt><dd id="offline-status">正在检查…</dd></div><div><dt>${ui.native?'本机存储':'浏览器存储'}</dt><dd id="storage-status">正在检查…</dd></div></dl>${ui.native?'':button('persist-storage','请求保留本地数据','secondary')}<p class="quiet-note">${ui.native?'卸载应用或清除应用数据会清除本地记录。':'清理浏览器数据会清除本地记录。'}关闭与重开会恢复已保存数据；日记与整理草稿单独保存在本机，可继续编辑。</p></section><section class="card">${ui.native?'<h2>离线使用与更新</h2><p>安装包已包含全部页面资源。记录与查看不需要电脑或网络；照片从系统文件选择器添加。</p><p>完整备份与文字导出会打开系统保存窗口，由你选择位置。网页与应用各自存储，可通过完整备份转移。</p><p class="quiet-note">更新请直接覆盖安装同签名的新版本，保留现有数据；先导出一份完整备份。不要先卸载。</p>':`<h2>浏览器试用</h2><p>可以手动计时、查看成长和保存图文。记录只在当前浏览器与网址中保存。</p><p>更换设备、浏览器或在网页与安卓应用之间转移，请使用完整备份；不会自动同步。</p><p class="quiet-note">HTTPS首次加载完成后可缓存离线资源。浏览器省电或清理数据仍会影响后台和保存，建议定期导出备份。</p>`}</section></div></details><details class="card section-fold" id="settings-help" data-preserve><summary>使用说明与活动管理</summary><p>开始与接力都从现在计时。补记请填写确定的范围，按分钟确认也正常累计。重叠会要求先调整范围；停止后不补造活动。</p><p>重新打开运行中的计时，会让你确认离开期间是否仍在做这件事。未确认尾段不自动进入成长；已保存的事实保留。你也可以只结束到确定的时间。</p><p>照片与感受可以附在活动上；没有计时也可留独立片段。时间纠错不会删除它们。成果是否完成、能力是否达到，都需要你的明确判断。</p>${button('setup-guide','初始设置引导','secondary')}${button('manage-activities','管理活动与关联','secondary')}${button('growth-info','成长数值说明','text-button')}</details><details class="card section-fold" id="settings-reset" data-preserve><summary>清空与重新开始</summary><section class="danger-zone"><div><h2>重新开始</h2><p>清空当前数据需要输入确认文字；清空前保留本机恢复点。</p></div>${button('reset','清空当前数据','danger-button')}</section></details>`;}

export function plans(state,ui){return originalPlans(state,ui)+weeklyPlans(state,ui,{e,button});}
export function insights(state,ui){return originalInsights(state,ui)+weeklyInsights(state,ui,{e,button,duration,num});}
